#![cfg(unix)]
#[cfg(feature="test-hook")]
#[test]fn private_socket_auth_and_cleanup(){use atlas_llama_probe::Encoder;use std::os::unix::{fs::{PermissionsExt,FileTypeExt},net::UnixStream};use std::io::{Read,Write};let model=Encoder::start("/private/tmp/atlas-llama-bin/llama-b12001/llama-server","/private/tmp/atlas-embeddinggemma-bf16.gguf").unwrap();let path=model.socket_path().to_owned();let dir=path.parent().unwrap().to_owned();assert_eq!(std::fs::metadata(&dir).unwrap().permissions().mode()&0o777,0o700);assert!(std::fs::metadata(&path).unwrap().file_type().is_socket());let mut conn=UnixStream::connect(&path).unwrap();conn.write_all(b"POST /v1/embeddings HTTP/1.1\r\nHost: localhost\r\nContent-Type: application/json\r\nContent-Length: 31\r\nConnection: close\r\n\r\n{\"input\":\"test\",\"model\":\"local\"}").unwrap();let mut reply=String::new();conn.read_to_string(&mut reply).unwrap();assert!(reply.starts_with("HTTP/1.1 401"),"{reply}");assert_eq!(model.encode("проверка",true).unwrap().len(),512);drop(model);assert!(!dir.exists());}
